import 'server-only'

type PageViewEvent = {
  event: 'page_view'
  path: string
  occurredAt: string
}

export async function logPageView(path: string): Promise<void> {
  const event: PageViewEvent = {
    event: 'page_view',
    path,
    occurredAt: new Date().toISOString(),
  }
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    // Structured server logs can be collected by the hosting platform.
    console.info('[analytics]', JSON.stringify(event))
    return
  }

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(event),
      cache: 'no-store',
    })

    if (!response.ok) {
      console.error(`[analytics] Page view request failed with status ${response.status}`)
    }
  } catch (error) {
    // Analytics failures should not affect the page response.
    console.error('[analytics] Failed to send page view', error)
  }
}
